def main():
    cur = open(PATH, encoding='utf-8').read() if os.path.exists(PATH) else ''
    if SENTINEL in cur:
        cur = cur[:cur.index(SENTINEL)]
    cur = re.sub(r'(\s*-{3,})+\s*$', '', cur).rstrip()
    out = cur + '\n' + CH if cur else CH.lstrip('\n')

    # ---------- 写盘前质检（§3.139l） ----------
    chapters = re.findall(r'^## ', out, flags=re.M)
    placeholders = re.findall(r'@[A-Z_0-9]+@', out)
    dup_unit = re.findall(r'元\s+元', out)
    sep_runs = re.findall(r'(?:^---\s*$\n){2,}', out, flags=re.M)
    assert len(chapters) == 3, f'章节数 {len(chapters)} != 3'
    assert not placeholders, f'残留占位符 {placeholders[:5]}'
    assert not dup_unit, f'「元 元」重复后缀 {len(dup_unit)} 处'
    assert not sep_runs, f'连续 --- 分隔线 {len(sep_runs)} 处'
    assert out.count(SENTINEL) == 1, '盘后章节哨兵重复'
    open(PATH, 'w', encoding='utf-8').write(out)
    print(f'✅ 已追加「三、盘后复盘」：{len(out.splitlines())} 行 / 章节 {len(chapters)} / '
          f'占位符 0 / 「元 元」0 / 连续 --- 0')


if __name__ == '__main__':
    main()
